const crypto = require('crypto');
const stringify = require('json-stable-stringify');
const logger = require('../utils/logger');
const redisClient = require('./redisClient');

const memoryStore = new Map();

const metrics = {
  hits: 0,
  misses: 0,
  sets: 0,
  deletes: 0,
  flushes: 0,
  lastHitAt: null,
  lastMissAt: null,
  lastSetAt: null,
  lastDeleteAt: null,
  lastFlushAt: null,
  lastError: null,
};

function markHit() {
  metrics.hits += 1;
  metrics.lastHitAt = new Date().toISOString();
}

function markMiss() {
  metrics.misses += 1;
  metrics.lastMissAt = new Date().toISOString();
}

function markSet() {
  metrics.sets += 1;
  metrics.lastSetAt = new Date().toISOString();
}

function markDelete() {
  metrics.deletes += 1;
  metrics.lastDeleteAt = new Date().toISOString();
}

function markFlush() {
  metrics.flushes += 1;
  metrics.lastFlushAt = new Date().toISOString();
}

function recordError(err) {
  metrics.lastError = err?.message || String(err);
}

function cacheEnabled() {
  return process.env.CACHE_ENABLED !== 'false';
}

function defaultTtlSeconds() {
  return parseInt(process.env.CACHE_DEFAULT_TTL || '60', 10);
}

function useRedis() {
  return cacheEnabled() && redisClient.isRedisEnabled();
}

function nowMs() {
  return Date.now();
}

async function get(key) {
  if (!cacheEnabled() || !key) return null;

  if (useRedis()) {
    try {
      const client = redisClient.getClient();
      const raw = await client.get(key);
      if (raw) {
        markHit();
        return JSON.parse(raw);
      }
      markMiss();
      return null;
    } catch (error) {
      logger.warn('Cache get failed', { key, error: error.message });
      recordError(error);
      return null;
    }
  }

  const entry = memoryStore.get(key);
  if (!entry) return null;
  if (entry.expiresAt && entry.expiresAt <= nowMs()) {
    memoryStore.delete(key);
    markMiss();
    return null;
  }
  markHit();
  return entry.value;
}

async function set(key, value, { ttlSeconds } = {}) {
  if (!cacheEnabled() || !key) return false;
  const ttl = parseInt(ttlSeconds, 10) > 0 ? parseInt(ttlSeconds, 10) : defaultTtlSeconds();

  if (useRedis()) {
    try {
      const client = redisClient.getClient();
      await client.set(key, JSON.stringify(value), 'EX', ttl);
      markSet();
      return true;
    } catch (error) {
      logger.warn('Cache set failed', { key, error: error.message });
      recordError(error);
      return false;
    }
  }

  memoryStore.set(key, { value, expiresAt: nowMs() + ttl * 1000 });
  markSet();
  return true;
}

async function del(key) {
  if (!cacheEnabled() || !key) return;

  if (useRedis()) {
    try {
      const client = redisClient.getClient();
      await client.del(key);
      markDelete();
    } catch (error) {
      logger.warn('Cache delete failed', { key, error: error.message });
      recordError(error);
    }
    return;
  }

  if (memoryStore.delete(key)) {
    markDelete();
  }
}

async function delPattern(pattern) {
  if (!cacheEnabled() || !pattern) return;

  if (useRedis()) {
    const client = redisClient.getClient();
    let cursor = '0';
    do {
      try {
        // eslint-disable-next-line no-await-in-loop
        const [nextCursor, keys] = await client.scan(cursor, 'MATCH', pattern, 'COUNT', '100');
        cursor = nextCursor;
        if (keys.length) {
          // eslint-disable-next-line no-await-in-loop
          await client.del(...keys);
          metrics.deletes += keys.length;
          metrics.lastDeleteAt = new Date().toISOString();
        }
      } catch (error) {
        logger.warn('Cache pattern delete failed', { pattern, error: error.message });
        recordError(error);
        return;
      }
    } while (cursor !== '0');
    return;
  }

  [...memoryStore.keys()].forEach((key) => {
    if (key.startsWith(pattern.replace('*', ''))) {
      memoryStore.delete(key);
      markDelete();
    }
  });
}

async function wrap(key, fetcher, { ttlSeconds, forceRefresh = false } = {}) {
  if (!forceRefresh) {
    const cached = await get(key);
    if (cached !== null && cached !== undefined) {
      return cached;
    }
  }

  const value = await fetcher();
  if (value !== undefined) {
    await set(key, value, { ttlSeconds });
  }
  return value;
}

async function flushAll() {
  if (!cacheEnabled()) return;

  if (useRedis()) {
    try {
      await redisClient.getClient().flushdb();
      markFlush();
    } catch (error) {
      logger.warn('Cache flush failed', { error: error.message });
      recordError(error);
    }
    return;
  }

  memoryStore.clear();
  markFlush();
}

function buildKey(namespace, identifier) {
  return `${namespace}::${identifier}`;
}

function buildListKey(namespace, payload) {
  const hash = crypto.createHash('sha1').update(stringify(payload || {})).digest('hex');
  return `${namespace}::${hash}`;
}

function buildPattern(namespace) {
  return `${namespace}::*`;
}

function getMetrics() {
  const attempts = metrics.hits + metrics.misses;
  const hitRate = attempts > 0 ? Number((metrics.hits / attempts).toFixed(4)) : null;
  return {
    enabled: cacheEnabled(),
    driver: useRedis() ? 'redis' : 'memory',
    redisConnected: redisClient.isConnected(),
    redisEnabled: redisClient.isRedisEnabled(),
    memoryFallback: redisClient.isMemoryFallback(),
    hits: metrics.hits,
    misses: metrics.misses,
    hitRate,
    sets: metrics.sets,
    deletes: metrics.deletes,
    flushes: metrics.flushes,
    lastHitAt: metrics.lastHitAt,
    lastMissAt: metrics.lastMissAt,
    lastSetAt: metrics.lastSetAt,
    lastDeleteAt: metrics.lastDeleteAt,
    lastFlushAt: metrics.lastFlushAt,
    lastError: metrics.lastError,
  };
}

module.exports = {
  isEnabled: cacheEnabled,
  get,
  set,
  del,
  delPattern,
  flushAll,
  wrap,
  buildKey,
  buildListKey,
  buildPattern,
  defaultTtlSeconds,
  getMetrics,
};
